css:
hr.thick-black-shadow {
    border: none;
    height: 2px;
    background-color: #000000;
    box-shadow: 0 3px 8px rgba(0, 0, 0, 0.4);
    margin: 20px 0;
}
    .rectangle-checkbox {
        margin-left: 10px;
        appearance: none;
        width: 18px;
        height: 18px;
        border: 2px solid #000;
        background-color: #fff;
        cursor: pointer;
        vertical-align: middle;
    }
    
    .rectangle-checkbox:checked {
        background-color: #000;
        position: relative;
    }
    
    .rectangle-checkbox:checked::after {
        content: "✓";
        color: #fff;
        position: relative;
        top: -2px;
        left: 2px;
        font-size: 14px;
    }
    
    .checkbox-li {
        display: flex;
        align-items: center;
        margin-bottom: 8px;
    }
    
    .checkbox-label {
        width: 120px;
        display: inline-block;
    }
